import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.BS0bAV7E.js";const b=JSON.parse('{"title":"内部机制：OTA/A-B 运作原理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/internals/ota-ab.md","filePath":"zh/internals/ota-ab.md"}'),d={name:"zh/internals/ota-ab.md"};function l(i,a,n,c,s,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="内部机制-ota-a-b-运作原理" tabindex="-1">内部机制：OTA/A-B 运作原理 <a class="header-anchor" href="#内部机制-ota-a-b-运作原理" aria-label="Permalink to &quot;内部机制：OTA/A-B 运作原理&quot;">​</a></h1><p><code>kernel/ota/ota_ab.{c,h}</code> + <code>ota_update.{c,h}</code>。</p><h2 id="槽位状态机" tabindex="-1">槽位状态机 <a class="header-anchor" href="#槽位状态机" aria-label="Permalink to &quot;槽位状态机&quot;">​</a></h2><p>每个槽位包含：内核镜像、grub.cfg 配置段、状态（启动中 / 成功 / 失败）。启动标志位选择活动槽位；GRUB 菜单会读取该标志位（ISO 入口会查询它，强制入口会覆盖它）。</p><h2 id="安装到非活动槽位" tabindex="-1">安装到非活动槽位 <a class="header-anchor" href="#安装到非活动槽位" aria-label="Permalink to &quot;安装到非活动槽位&quot;">​</a></h2><p><code>update install &lt;slot&gt;</code> 将已验证包的内核写入非活动槽位并设置启动标志位。您将继续在当前槽位上运行直到重启 - 写入失败绝不会触及您的运行系统。</p><h2 id="切换后的首次启动" tabindex="-1">切换后的首次启动 <a class="header-anchor" href="#切换后的首次启动" aria-label="Permalink to &quot;切换后的首次启动&quot;">​</a></h2><p>新槽位以&quot;启动中&quot;状态启动；成功的用户空间启动会将其标记为&quot;成功&quot;（E2E 测试会验证此过程）；如果它从未确认，标志位将回退 - 这加上手动强制入口，就是回滚机制。</p><h2 id="验证链" tabindex="-1">验证链 <a class="header-anchor" href="#验证链" aria-label="Permalink to &quot;验证链&quot;">​</a></h2><p>清单（update.json）-&gt; 包 SHA256 -&gt; 签名。三者都必须通过，安装才会触及槽位；失败时会明确指出失败阶段。</p><h2 id="内核内的-grub-有效载荷" tabindex="-1">内核内的 GRUB 有效载荷 <a class="header-anchor" href="#内核内的-grub-有效载荷" aria-label="Permalink to &quot;内核内的 GRUB 有效载荷&quot;">​</a></h2><p><code>tools/embed_grub.py</code> 将 boot.img + grub-mkimage 构建的 core.img（磁盘上 grub.cfg 所需的模块集）作为生成的 C 数据嵌入内核中 - 这就是 <code>install</code>/<code>abdisk</code>/<code>grub-install</code> 能在不依赖外部文件的情况下写入可启动磁盘的方式（即&quot;规则-9 自托管&quot;接口面）。</p>',12)])])}const p=e(d,[["render",l]]);export{b as __pageData,p as default};
